import json, pathlib
holders=[]
for process in pathlib.Path('/proc').iterdir():
 if not process.name.isdigit(): continue
 try:
  for info in (process/'fdinfo').iterdir():
   try:
    fields=dict(line.split(':',1) for line in info.read_text().splitlines() if ':' in line)
    if fields.get('map_id','').strip()=='76':
     holders.append({'pid':int(process.name),'fd':info.name,'comm':(process/'comm').read_text().strip()})
   except (OSError,ValueError): pass
 except OSError: pass
print(json.dumps({'map_id':76,'fd_holders':holders}))
